117							List<StatoDomanda> statiCustom = statoDomandaLocalService.getStatoDomandaByBandoId(bandoId);
118							
119							if(Validator.isNotNull(statiCustom) && !statiCustom.isEmpty()) {
120								Optional<StatoDomanda> statoCustomTrovato = statiCustom.stream().filter(x -> x.getCodice().equalsIgnoreCase(statoDomanda)).findFirst();
121								
122								if(statoCustomTrovato.isPresent() && Validator.isNotNull(statoCustomTrovato.get())) {
123									StatoDomanda stato = statoCustomTrovato.get();
124									
125									if(stato.getStatoDomandaId()>0) {
126										utentiId = domandaBandoLocalService.getDomandeBandoByBandoId(bandoId)
127												.stream()
128												.filter(domandaBando -> domandaBando.getStatoId() == stato.getStatoDomandaId())
129												.map(domandaBando -> domandaBando.getUserId())
130												.distinct()
131												.collect(Collectors.toList()); 
132									}
133								}else {
134									if(Validator.isNotNull(statoInterno)) {
135										utentiId = domandaBandoLocalService.getDomandeBandoByBandoId(bandoId)
136												.stream()
137												.filter(domandaBando -> domandaBando.getStato().equalsIgnoreCase(statoInterno.name()))
138												.map(domandaBando -> domandaBando.getUserId())
139												.distinct()
140												.collect(Collectors.toList()); 
141									}
142								}
143							}
144	
145	
146						}
147					} else if (Dominio.SERVIZIO.equals(dominio)) {
148						Servizio servizio = servizioLocalService.getServizioByCodice(itemId);
149						if (Validator.isNotNull(servizio)) {
150							List<Richiesta> richieste = richiestaLocalService.getRichiesteByServizioId(servizio.getServizioId());
151							if (Validator.isNotNull(richieste) && !richieste.isEmpty()) {
152								utentiId = richieste
153										.stream()
154										.map(r -> r.getUserId())
155										.distinct()
156										.collect(Collectors.toList());
157							}
158						}
159						
160					}
161				}else {
162					utentiId.add(utente);
163				}
164				
165				if(Validator.isNotNull(utentiId) && !utentiId.isEmpty()) {
166					
167					Comunicazione comunicazione = comunicazioneLocalService.addComunicazione(
168							ctx,
169							titolo,
170							messaggio,
171							getLocalDateTime(dataInizio),
172							getLocalDateTime(dataFine),
173							interna,
174							dominio,
175							itemId,
176							tipologia,
177							sottoOrganizzazione,
178							reply
179					);
180					
181					
182					destinatarioComunicazioneLocalService.addDestinatarioComunicazione(ctx, comunicazione.getComunicazioneId(), utentiId);
183					letturaMessaggioLocalService.setMessaggiLetti(comunicazione.getComunicazioneId(), ctx.getUserId());
184				}
185				
186	
187				
188			} catch (ComunicazioneTitoloException e) {
189				params.setValue("mvcRenderCommandName", "/render/nuova");
190				SessionErrors.add(request, "errore-titolo");
191				auditService.saveErrorLog(request, "No titolo");
192			} catch (ComunicazioneMessaggioException e) {
193				params.setValue("mvcRenderCommandName", "/render/nuova");
194				SessionErrors.add(request, "errore-descrizione");
195				auditService.saveErrorLog(request, "No descrizione");
196			} catch (ComunicazioneOrganizzazioneException e) {
197				params.setValue("mvcRenderCommandName", "/render/nuova");
198				SessionErrors.add(request, "errore-ente");
199				auditService.saveErrorLog(request, "No ente");
200			} catch (ComunicazioneDataFineException e) {
201				params.setValue("mvcRenderCommandName", "/render/nuova");
202				SessionErrors.add(request, "errore-data-fine");
203				auditService.saveErrorLog(request, "No data fine");
204			} catch (Exception e) {
205				params.setValue("mvcRenderCommandName", "/render/nuova");
206				auditService.saveErrorLog(request, e.getMessage());
207				SessionErrors.add(request, "errore-generico");
208			}
209		}
210		
211		private Date getLocalDateTime(String val) {
212			if (val.isEmpty()) {
213				return null;
214			} else {
215				try {
216					return FORMATTER.parse(val);
217				} catch (ParseException e) {
218					throw new RuntimeException(e);
219				}
220			}
221		}
222	
223	}
