package it.servizidigitali.gestionecomunicazioni.frontend.portlet.action;

import com.liferay.portal.kernel.portlet.bridges.mvc.BaseMVCActionCommand;
import com.liferay.portal.kernel.portlet.bridges.mvc.MVCActionCommand;
import com.liferay.portal.kernel.service.ServiceContext;
import com.liferay.portal.kernel.service.ServiceContextFactory;
import com.liferay.portal.kernel.servlet.SessionErrors;
import com.liferay.portal.kernel.util.ParamUtil;
import com.liferay.portal.kernel.util.Validator;

import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;

import javax.portlet.ActionRequest;
import javax.portlet.ActionResponse;
import javax.portlet.MutableRenderParameters;

import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Reference;

import it.servizidigitali.audit.common.service.AuditService;
import it.servizidigitali.gestionebandi.model.StatoDomanda;
import it.servizidigitali.gestionebandi.service.DomandaBandoLocalService;
import it.servizidigitali.gestionebandi.service.StatoDomandaLocalService;
import it.servizidigitali.gestionecomunicazioni.exception.ComunicazioneDataFineException;
import it.servizidigitali.gestionecomunicazioni.exception.ComunicazioneMessaggioException;
import it.servizidigitali.gestionecomunicazioni.exception.ComunicazioneOrganizzazioneException;
import it.servizidigitali.gestionecomunicazioni.exception.ComunicazioneTitoloException;
import it.servizidigitali.gestionecomunicazioni.frontend.constants.GestioneComunicazioniFrontendPortletKeys;
import it.servizidigitali.gestionecomunicazioni.frontend.enumeration.StatoDomandaBandoEnum;
import it.servizidigitali.gestionecomunicazioni.model.Comunicazione;
import it.servizidigitali.gestionecomunicazioni.model.Dominio;
import it.servizidigitali.gestionecomunicazioni.service.ComunicazioneLocalService;
import it.servizidigitali.gestionecomunicazioni.service.DestinatarioComunicazioneLocalService;
import it.servizidigitali.gestionecomunicazioni.service.LetturaMessaggioLocalService;
import it.servizidigitali.gestionecomunicazioni.service.MessaggioLocalService;
import it.servizidigitali.gestioneservizi.model.Servizio;
import it.servizidigitali.gestioneservizi.service.ServizioLocalService;
import it.servizidigitali.scrivaniaoperatore.model.Richiesta;
import it.servizidigitali.scrivaniaoperatore.service.IstanzaFormLocalService;
import it.servizidigitali.scrivaniaoperatore.service.RichiestaLocalService;

@Component(
		immediate = true,
		service = MVCActionCommand.class,
		property = {
				"javax.portlet.name=" + GestioneComunicazioniFrontendPortletKeys.GESTIONECOMUNICAZIONI,
				"mvc.command.name=/action/inserisci"
		}
)
public class InserisciActionCommand extends BaseMVCActionCommand {

	private static final SimpleDateFormat FORMATTER = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm");

	@Reference
	private ComunicazioneLocalService comunicazioneLocalService;
	@Reference
	private AuditService auditService;
	@Reference
	private LetturaMessaggioLocalService letturaMessaggioLocalService;
	@Reference
	private DomandaBandoLocalService domandaBandoLocalService;
	@Reference
	private DestinatarioComunicazioneLocalService destinatarioComunicazioneLocalService;
	@Reference
	private MessaggioLocalService messaggioLocalService;
	@Reference
	private StatoDomandaLocalService statoDomandaLocalService;
	@Reference
	private RichiestaLocalService richiestaLocalService;
	@Reference
	private ServizioLocalService servizioLocalService;

	@Override
	protected void doProcessAction(ActionRequest request, ActionResponse response) throws Exception {
		String titolo = ParamUtil.getString(request, "titolo").trim();
		long tipologia = ParamUtil.getLong(request, "tipologia");
		String messaggio = ParamUtil.getString(request, "messaggio");
		String dataInizio = ParamUtil.getString(request, "dataInizio");
		String dataFine = ParamUtil.getString(request, "dataFine");
		String codiceServizio = ParamUtil.getString(request, "servizio");
		long bandoId = ParamUtil.getLong(request, "bando");
		long sottoOrganizzazione = ParamUtil.getLong(request, "organizzazione");
		long utente = ParamUtil.getLong(request, "utente");
		boolean interna = ParamUtil.getBoolean(request, "interna");
		String statoDomanda = ParamUtil.getString(request, "statoDomanda");
		boolean reply = ParamUtil.getBoolean(request, "comunicazione-sola-lettura");

		MutableRenderParameters params = response.getRenderParameters();

		try {
			ServiceContext ctx = ServiceContextFactory.getInstance(request);

			Dominio dominio = bandoId == 0 ? Dominio.SERVIZIO : Dominio.BANDO;
			String itemId = Dominio.SERVIZIO.equals(dominio) ? codiceServizio : String.valueOf(bandoId);

			List<Long> utentiId = new ArrayList<Long>();

			//utente == 0 --> invio mail a tutti gli utenti del bando selezionato
			if(utente == 0) {
				if (Dominio.BANDO.equals(dominio)) {
					if(Validator.isNull(statoDomanda)) {
						//stato settato su tutti
						utentiId = domandaBandoLocalService.getDomandeBandoByBandoId(bandoId)
								.stream()
								.map(domandaBando -> domandaBando.getUserId())
								.distinct()
								.collect(Collectors.toList()); 
					}else {
						//stato custom
						StatoDomandaBandoEnum statoInterno = StatoDomandaBandoEnum.findByName(statoDomanda);
						List<StatoDomanda> statiCustom = statoDomandaLocalService.getStatoDomandaByBandoId(bandoId);

						if(Validator.isNotNull(statiCustom) && !statiCustom.isEmpty()) {
							Optional<StatoDomanda> statoCustomTrovato = statiCustom.stream().filter(x -> x.getCodice().equalsIgnoreCase(statoDomanda)).findFirst();

							if(statoCustomTrovato.isPresent() && Validator.isNotNull(statoCustomTrovato.get())) {
								StatoDomanda stato = statoCustomTrovato.get();

								if(stato.getStatoDomandaId()>0) {
									utentiId = domandaBandoLocalService.getDomandeBandoByBandoId(bandoId)
											.stream()
											.filter(domandaBando -> domandaBando.getStatoId() == stato.getStatoDomandaId())
											.map(domandaBando -> domandaBando.getUserId())
											.distinct()
											.collect(Collectors.toList()); 
								}
							}else {
								if(Validator.isNotNull(statoInterno)) {
									utentiId = domandaBandoLocalService.getDomandeBandoByBandoId(bandoId)
											.stream()
											.filter(domandaBando -> domandaBando.getStato().equalsIgnoreCase(statoInterno.name()))
											.map(domandaBando -> domandaBando.getUserId())
											.distinct()
											.collect(Collectors.toList()); 
								}
							}
						}


					}
				} else if (Dominio.SERVIZIO.equals(dominio)) {
					Servizio servizio = servizioLocalService.getServizioByCodice(itemId);
					if (Validator.isNotNull(servizio)) {
						List<Richiesta> richieste = richiestaLocalService.getRichiesteByServizioId(servizio.getServizioId());
						if (Validator.isNotNull(richieste) && !richieste.isEmpty()) {
							utentiId = richieste
									.stream()
									.map(r -> r.getUserId())
									.distinct()
									.collect(Collectors.toList());
						}
					}

				}
			}else {
				utentiId.add(utente);
			}

			if(Validator.isNotNull(utentiId) && !utentiId.isEmpty()) {

				Comunicazione comunicazione = comunicazioneLocalService.addComunicazione(
						ctx,
						titolo,
						messaggio,
						getLocalDateTime(dataInizio),
						getLocalDateTime(dataFine),
						interna,
						dominio,
						itemId,
						tipologia,
						sottoOrganizzazione,
						reply
				);


				destinatarioComunicazioneLocalService.addDestinatarioComunicazione(ctx, comunicazione.getComunicazioneId(), utentiId);
				letturaMessaggioLocalService.setMessaggiLetti(comunicazione.getComunicazioneId(), ctx.getUserId());
			}



		} catch (ComunicazioneTitoloException e) {
			params.setValue("mvcRenderCommandName", "/render/nuova");
			SessionErrors.add(request, "errore-titolo");
			auditService.saveErrorLog(request, "No titolo");
		} catch (ComunicazioneMessaggioException e) {
			params.setValue("mvcRenderCommandName", "/render/nuova");
			SessionErrors.add(request, "errore-descrizione");
			auditService.saveErrorLog(request, "No descrizione");
		} catch (ComunicazioneOrganizzazioneException e) {
			params.setValue("mvcRenderCommandName", "/render/nuova");
			SessionErrors.add(request, "errore-ente");
			auditService.saveErrorLog(request, "No ente");
		} catch (ComunicazioneDataFineException e) {
			params.setValue("mvcRenderCommandName", "/render/nuova");
			SessionErrors.add(request, "errore-data-fine");
			auditService.saveErrorLog(request, "No data fine");
		} catch (Exception e) {
			params.setValue("mvcRenderCommandName", "/render/nuova");
			auditService.saveErrorLog(request, e.getMessage());
			SessionErrors.add(request, "errore-generico");
		}
	}

	private Date getLocalDateTime(String val) {
		if (val.isEmpty()) {
			return null;
		} else {
			try {
				return FORMATTER.parse(val);
			} catch (ParseException e) {
				throw new RuntimeException(e);
			}
		}
	}

}

