package it.servizidigitali.gestionecomunicazioni.service.impl;

import java.util.List;

import org.osgi.service.component.annotations.Component;

import com.liferay.portal.aop.AopService;
import com.liferay.portal.kernel.exception.PortalException;
import com.liferay.portal.kernel.log.Log;
import com.liferay.portal.kernel.log.LogFactoryUtil;
import com.liferay.portal.kernel.model.User;
import com.liferay.portal.kernel.service.ServiceContext;
import com.liferay.portal.kernel.util.OrderByComparatorFactoryUtil;

import it.servizidigitali.gestionecomunicazioni.exception.NoSuchMessaggioException;
import it.servizidigitali.gestionecomunicazioni.model.Messaggio;
import it.servizidigitali.gestionecomunicazioni.service.base.MessaggioLocalServiceBaseImpl;

/**
 * @author Brian Wing Shun Chan
 */
@Component(
	property = "model.class.name=it.servizidigitali.gestionecomunicazioni.model.Messaggio",
	service = AopService.class
)
public class MessaggioLocalServiceImpl extends MessaggioLocalServiceBaseImpl {

	public static final Log _log = LogFactoryUtil.getLog(MessaggioLocalServiceImpl.class);


	@Override
	public Messaggio aggiungiMessaggio(ServiceContext serviceContext, long comunicazioneId, String contenuto) {
		User user;
		try {
			user = userLocalService.getUser(serviceContext.getUserId());
		} catch (PortalException e) {
			throw new RuntimeException(e);
		}

		long messaggioId = counterLocalService.increment(Messaggio.class.getName());
		Messaggio messaggio = messaggioPersistence.create(messaggioId);
		messaggio.setComunicazioneId(comunicazioneId);
		messaggio.setContenuto(contenuto);
		messaggio.setUserName(user.getFullName());
		messaggio.setCompanyId(serviceContext.getCompanyId());
		messaggio.setUserId(serviceContext.getUserId());
		messaggio.setGroupId(serviceContext.getScopeGroupId());
		return messaggioPersistence.update(messaggio);
	}

	@Override
	public List<Messaggio> getMessaggi(long comunicazioneId, int start, int end) {
		return messaggioPersistence.findByComunicazione(
				comunicazioneId, 
				start, end,
				OrderByComparatorFactoryUtil.create("Messaggio", "createDate", true));
	}

	@Override
	public Messaggio getFirstMessaggio(long comunicazioneId) {

		Messaggio messaggio = null;

		try {
			messaggio = messaggioPersistence.findByComunicazione_First(comunicazioneId, OrderByComparatorFactoryUtil.create("Messaggio", "createDate", false));

		}catch(NoSuchMessaggioException e) {
			_log.debug(e.getMessage());
		}

		return messaggio;
	}

	@Override
	public int countMessaggi(long comunicazioneId) {
		return messaggioPersistence.countByComunicazione(comunicazioneId);
	}

	@Override
	public List<Long> findComunicazioneIdsByMessaggioIds(List<Long> messaggioIds){
		return messaggioFinder.findComunicazioneIdsByMessaggioIds(messaggioIds);
	}

	@Override
	public List<Messaggio> findMessaggiByComunicazioneIdAndNotUserId(Long comunicazioneId, Long userId, int start, int end) {
		return messaggioFinder.findMessaggiByComunicazioneIdAndNotUserId(comunicazioneId, userId, start, end);
	}

	@Override
	public List<Messaggio> findMessaggiByComunicazioneIdAndNotUserIds(Long comunicazioneId, long userId, long[] userIdsOperatori, int start, int end) {
		return messaggioFinder.findMessaggiByComunicazioneIdAndNotUserIds(comunicazioneId, userId, userIdsOperatori, start, end);
	}
}

