package it.servizidigitali.gestionecomunicazioni.frontend.dto;

import java.util.Date;
import java.util.List;

public class ComunicazioneDTO {
	private long id;
	private Date dataInvio;
	private String titolo;
	private String tipologia;
	private String stato;
	private String ente;
	private int numMess;
	private long richiestaId;
	private long domandaBandoId;
	private String destinatarioCodiceFiscale;
	private String destinatarioFullName;
	private List<Messaggio> messaggi;

	public long getId() {
		return id;
	}
