		this.titolo = titolo;
	}
	public String getTipologia() {
		return tipologia;
	}
	public void setTipologia(String tipologia) {
		this.tipologia = tipologia;
	}
	public String getStato() {
		return stato;
	}
	public void setStato(String stato) {
		this.stato = stato;
	}
	public String getEnte() {
		return ente;
	}
	public void setEnte(String ente) {
		this.ente = ente;
	}

	public int getNumMess() {
		return numMess;
	}

	public void setNumMess(int numMess) {
		this.numMess = numMess;
	}

	public List<Messaggio> getMessaggi() {
		return messaggi;
	}

	public void setMessaggi(List<Messaggio> messaggi) {
		this.messaggi = messaggi;
	}

	public long getRichiestaId() {
		return richiestaId;
	}
	public void setRichiestaId(long richiestaId) {
		this.richiestaId = richiestaId;
	}
	public long getDomandaBandoId() {
		return domandaBandoId;
	}
	public void setDomandaBandoId(long domandaBandoId) {
		this.domandaBandoId = domandaBandoId;
	}
	public String getDestinatarioCodiceFiscale() {
		return destinatarioCodiceFiscale;
	}
	public void setDestinatarioCodiceFiscale(String destinatarioCodiceFiscale) {
		this.destinatarioCodiceFiscale = destinatarioCodiceFiscale;
	}


	public String getDestinatarioFullName() {
		return destinatarioFullName;
	}
	public void setDestinatarioFullName(String destinatarioFullName) {
		this.destinatarioFullName = destinatarioFullName;
	}


	public static class Messaggio {
		private long id;
		private Date data;
		private long userId;
		private String username;
		private String contenuto;
		private String screenName;

		public long getId() {
			return id;
		}

